"""Add the Halloween teams to the Champions Player Pick catalogue (red Champions design).
Each card is pickable only while its team is in packs; 84s join once the Blutmond upgrade makes them 85."""
import csv, json, subprocess
from datetime import datetime
from pathlib import Path
root = Path(__file__).resolve().parent.parent
source = """const fs=require('fs'),vm=require('vm'),s=fs.readFileSync('footera-app.js','utf8'),c={};for(const n of ['HALLOWEEN_EVENT','HALLOWEEN_TEAM2_EVENT']){const a=s.indexOf('const '+n+'='),b=s.indexOf('\\n]};',a)+4;vm.runInNewContext(s.slice(a,b)+';this.'+n+'='+n,c)}process.stdout.write(JSON.stringify(c));"""
evs=json.loads(subprocess.check_output(['node','-e',source],cwd=root))
team1,team2=evs['HALLOWEEN_EVENT'],evs['HALLOWEEN_TEAM2_EVENT']
upgrade=team1['upgrade']
with (root/'assets/players-db.csv').open() as f: rows=list(csv.DictReader(f))
byid={r['player_id']:r for r in rows}; teams={r['club_name']:r for r in rows if r['gender']=="Men's Football"}
t=datetime.fromisoformat
# Team 1 leaves the packs when Team 2 starts; Team 2 runs to its own end.
windows=[(team1,1,team1['activeFrom'],team2['activeFrom']),(team2,2,team2['activeFrom'],team2['activeUntilAt'])]
q=lambda x:"'"+str(x).replace("'","''")+"'"
out=[]
for ev,n,start,end in windows:
 for p in ev['players']:
  r=byid[p['pid']]; club=teams.get(p['team'],{})
  starts=start; rating=p['ovr']
  if t(start)>=t(upgrade['at']): rating+=upgrade['ovr']
  if rating<85:
   if t(start)>=t(upgrade['at']) or rating+upgrade['ovr']<85: continue
   starts=upgrade['at']; rating+=upgrade['ovr']
  b={'id':p['pid'],'name':p['name'],'fullName':r['long_name'],'ovr':int(r['overall']),'position':p['position'],'alt':p.get('alt',''),'nation':p['nation'],'nationCode':r['nationality_id'],'nationFlag':r['nation_flag_url'],'team':p['team'],'teamId':club.get('club_team_id',''),'clubLogo':club.get('club_logo_url',''),'league':p.get('league',club.get('league_name','')),'face':r['player_face_url'],'gender':'male','source':'fc27-open-data','playstyles':r['playstyles'],'playstylesPlus':r['playstyles_plus'],'skillMoves':int(r['skill_moves']),'weakFoot':int(r['weak_foot'])}
  for k,col in zip(['pac','sho','pas','dri','def','phy'],['pace','shooting','passing','dribbling','defending','physic']): b[k]=int(r[col])
  # The stored card keeps its pre-upgrade values: the Blutmond +1 is applied at render time.
  item={'pid':p['pid'],'variant':'special','eventType':'halloween','eventName':'HALLOWEEN','eventReleaseId':ev['id'],'displayRating':p['ovr'],'eventStats':p['stats'],'overridePosition':p['position'],'dynamicFace':p['dynamicFace'],'playstyleAdds':p.get('playstyleAdds',[]),'playstylePlusAdds':p.get('playstylePlusAdds',[]),'baseSnapshot':b,'tradeable':False,'rare':True,'evo':0,'evoStats':{}}
  out.append('('+','.join([q(f'halloween:{n}:{p["pid"]}'),q('special'),str(rating),q(starts)+'::timestamptz',q(end)+'::timestamptz',q(json.dumps(item,ensure_ascii=False,separators=(',',':')))+'::jsonb'])+')')
assert len(team1['players'])==18 and len(team2['players'])==18
(root/'online/footera-pick-catalog-halloween.sql').write_text('-- Generated by scripts/build-halloween-pick-catalog.py: Halloween cards in Champions Player Picks (shown red).\ninsert into public.footera_pick_catalog(id,kind,rating,starts_at,ends_at,item) values\n'+',\n'.join(out)+'\non conflict(id) do update set rating=excluded.rating,starts_at=excluded.starts_at,ends_at=excluded.ends_at,item=excluded.item;\n')
print('Generated',len(out),'cards')
